import argparse
import csv
import json

def parse_amount(amount_str):
    if not amount_str:
        return 0.0
    # Remove dollar sign and commas
    cleaned = amount_str.replace('$', '').replace(',', '')
    # Handle negative values
    if cleaned.startswith('-'):
        return -float(cleaned[1:])
    return float(cleaned)

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()

    payload = json.loads(args.payload)
    path = payload['path']

    total = 0.0

    with open(path, 'r', newline='') as f:
        reader = csv.reader(f)
        next(reader)  # Skip header
        for row in reader:
            if len(row) < 2:
                continue
            amount_str = row[1].strip()
            if amount_str:
                total += parse_amount(amount_str)

    print(f"{total:.2f}")

if __name__ == "__main__":
    main()

import argparse
import csv
import json

def parse_amount(amount_str):
    # Remove $ and commas, handle negative signs
    cleaned = amount_str.replace('$', '').replace(',', '').strip()
    if not cleaned:
        return 0.0
    return float(cleaned)

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    payload = json.loads(args.payload)
    path = payload["path"]

    total = 0.0
    with open(path, 'r', newline='') as csvfile:
        reader = csv.DictReader(csvfile)
        for row in reader:
            if row.get('amount') is not None:
                try:
                    total += parse_amount(row['amount'])
                except ValueError:
                    # Skip rows with invalid amount values
                    pass
    print(f"{total:.2f}")

if __name__ == "__main__":
    main()

import argparse
import json

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    payload = json.loads(args.payload)
    path = payload["path"]

    user_latest_actions = {}

    with open(path, 'r') as f:
        for line in f:
            if line.strip():
                event = json.loads(line)
                user_id = event['user']
                timestamp = event['ts']
                action = event['action']

                if user_id not in user_latest_actions or timestamp > user_latest_actions[user_id]['ts']:
                    user_latest_actions[user_id] = {'ts': timestamp, 'action': action}

    logout_count = sum(1 for item in user_latest_actions.values() if item['action'] == 'logout')

    print(logout_count)

if __name__ == "__main__":
    main()

import argparse
import json

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    payload = json.loads(args.payload)

    user_events = {}

    with open('/inputs/events2.jsonl', 'r') as f:
        for line in f:
            if line.strip():
                event = json.loads(line)
                user = event['user']
                if user not in user_events:
                    user_events[user] = []
                user_events[user].append(event)

    logout_count = 0

    for events in user_events.values():
        latest_event = max(events, key=lambda x: x['ts'])
        if latest_event['action'] == 'logout':
            logout_count += 1

    print(logout_count)

if __name__ == '__main__':
    main()

import argparse
import json

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    data = json.loads(args.payload)
    path = data['path']

    with open(path, 'r') as f:
        content = f.read().strip()

    if 'refund' in content.lower():
        print('refund')
    elif 'exchange' in content.lower():
        print('exchange')
    elif 'cancellation' in content.lower():
        print('cancellation')
    else:
        print('unknown')

if __name__ == '__main__':
    main()
